TRACK_ALIASES = {
    "NT": "K110", "4046": "K110", "K110": "K110",
    "NA": "K210", "4045": "K210", "K210": "K210",
    "O": "K310", "4052": "K310", "K310": "K310",
    "G2A": "K232", "4051": "K232", "K232": "K232",
    "G3A": "K341", "4049": "K341", "K341": "K341",
}

def canonical_track_code(code: str) -> str:
    return TRACK_ALIASES.get(str(code), str(code))

def topic_entries_for_track(code: str) -> list[dict]:
    return list(TRACK_TOPIC_CATALOG.get(canonical_track_code(code), []))

def paper_setting_topics(code: str) -> list[str]:
    return [row["name"] for row in topic_entries_for_track(code)]

def topic_notes_for_selection(code: str, selected_names: list[str]) -> str:
    chosen = set(selected_names or [])
    rows = [r for r in topic_entries_for_track(code) if r["name"] in chosen]
    if not rows: return ""
    parts = ["Authoritative syllabus scope from the uploaded learning-outcomes workbook:"]
    for r in rows:
        detail = " ".join(str(r.get("details", "")).split())
        outcomes = [" ".join(str(x).split()) for x in r.get("outcomes", [])[:3]]
        parts.append(f"- {r['name']}: {detail}")
        if outcomes: parts.append("  Learning-outcome focus: " + " | ".join(outcomes))
    return "\n".join(parts)

def offline_topic_rows(code: str) -> list[dict]:
    return topic_entries_for_track(code)
